const q = $input.first().json.query || {};
if (q['hub.verify_token'] === 'topauto2024secret') {
  return [{ json: { response: q['hub.challenge'] } }];
}
return [{ json: { response: 'Forbidden' } }];

const body = $input.first().json.body;

if (!body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  return [{ json: { skip: true, raison: 'pas_de_message' } }];
}

const value = body.entry[0].changes[0].value;
const message = value.messages[0];
const contact = value.contacts?.[0];

if (!['text', 'interactive'].includes(message.type)) {
  return [{ json: { skip: true, raison: 'type_non_supporte_' + message.type } }];
}

let texte = '';
let btn_id_recu = null;

const boutons_map = {
  'btn_achat':        'Je veux acheter un vehicule Renault ou Dacia et obtenir un devis',
  'btn_sav':          'Je veux prendre rendez-vous a l atelier pour entretien ou reparation',
  'btn_documents':    'J ai besoin d un document administratif : main levee, facture ou carte grise',
  'btn_localisation': 'Donnez-moi l adresse et les horaires de la concession',
  'btn_conseiller':   'Je veux etre contacte par un conseiller commercial immediatement',
  'btn_brochure':     'Je veux voir la gamme complete des vehicules disponibles'
};

if (message.type === 'text') {
  texte = (message.text?.body || '').trim().replace(/\s+/g, ' ');
} else if (message.type === 'interactive') {
  btn_id_recu = message.interactive?.button_reply?.id || '';
  texte = boutons_map[btn_id_recu] || message.interactive?.button_reply?.title || btn_id_recu;
}

if (!texte) {
  return [{ json: { skip: true, raison: 'texte_vide' } }];
}

const telephone = message.from;
const message_id = message.id;
const timestamp = new Date(parseInt(message.timestamp) * 1000).toISOString();
const phone_number_id = value.metadata?.phone_number_id || '1031404513398168';
const nom = contact?.profile?.name || 'Client';

const texte_upper = texte.toUpperCase().trim();
const est_reset = ['MENU', 'RETOUR', 'ACCUEIL', 'HOME', 'RESTART', 'RECOMMENCER'].includes(texte_upper);

return [{
  json: {
    telephone,
    nom,
    texte,
    texte_upper,
    btn_id_recu,
    message_id,
    timestamp,
    phone_number_id,
    est_reset,
    skip: false
  }
}];

// ============================================================
// 08 — GESTION SESSION (Static Data n8n)
// ============================================================
// On utilise le Static Data de n8n comme memoire de session
// Accessible via $getWorkflowStaticData('node') ou 'global'
// ============================================================
const d = $input.first().json;
const telephone = d.telephone;

// Acces a la memoire globale du workflow
const memoria = $getWorkflowStaticData('global');

// Initialiser le store si vide
if (!memoria.sessions) {
  memoria.sessions = {};
}

const SESSION_TIMEOUT_MS = 30 * 60 * 1000; // 30 minutes
const maintenant = Date.now();

// Recuperer session existante
let session = memoria.sessions[telephone] || null;

// Verifier expiration session
if (session && (maintenant - session.last_interaction) > SESSION_TIMEOUT_MS) {
  session = null; // Session expiree -> reset
}

// Reset manuel
if (d.est_reset) {
  session = null;
}

// Anti-duplicate: verifier si message_id deja traite
if (session && session.last_message_id === d.message_id) {
  return [{ json: { skip_duplicate: true } }];
}

// Determiner etat de la session
let est_nouveau = false;
let etat_actuel = 'ACTIF';
let langue = null;

if (!session) {
  // NOUVELLE SESSION
  est_nouveau = true;
  session = {
    telephone,
    nom: d.nom,
    langue: null,
    etat: 'ATTENTE_LANGUE',
    service_actuel: null,
    last_interaction: maintenant,
    last_message_id: d.message_id,
    created_at: maintenant
  };
} else {
  // SESSION EXISTANTE — mettre a jour
  session.last_interaction = maintenant;
  session.last_message_id = d.message_id;
  etat_actuel = session.etat || 'ACTIF';
  langue = session.langue;
}

// Sauvegarder session
// Reset forcé si session corrompue
if (session && !['ATTENTE_LANGUE', 'ATTENTE_MENU', 'ACTIF'].includes(session.etat)) {
  session = null;
  est_nouveau = true;
  session = {
    telephone,
    nom: d.nom,
    langue: null,
    etat: 'ATTENTE_LANGUE',
    service_actuel: null,
    last_interaction: maintenant,
    last_message_id: d.message_id,
    created_at: maintenant
  };
}

return [{
  json: {
    ...d,
    session,
    est_nouveau,
    etat_actuel: session.etat,
    langue_session: session.langue,
    skip_duplicate: false
  }
}];

